module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg prev_a;
reg current_a;

always @(posedge clk or negedge rst_n) begin

    if (!rst_n) begin

        prev_a <= 1'b0;
        current_a <= 1'b0;
    end else begin

        prev_a <= current_a;

        current_a <= a;
    end
end

always @(*) begin

    rise = 1'b0;
    down = 1'b0;

    if ((prev_a == 1'b0) && (current_a == 1'b1)) begin
        rise = 1'b1;
    end

    if ((prev_a == 1'b1) && (current_a == 1'b0)) begin
        down = 1'b1;
    end
end
endmodule
